const http = require('http');
const crypto = require('crypto');
const { URL } = require('url');

const SECRET = crypto.randomBytes(32);
const users = new Map();
const sessions = new Map();

// Sliding window rate limiter
class RateLimiter {
  constructor(windowMs, maxRequests) {
    this.windowMs = windowMs;
    this.maxRequests = maxRequests;
    this.windows = new Map();
  }

  // Returns true if request is allowed
  isAllowed(identifier) {
    const now = Date.now();
    const windowStart = this._computeWindowStart(now);

    if (!this.windows.has(identifier)) {
      this.windows.set(identifier, { start: windowStart, count: 1 });
      return true;
    }

    const record = this.windows.get(identifier);

    // Check if we're in a new window
    const elapsed = now - record.start;
    if (elapsed >= this.windowMs) {
      // Reset for new window
      record.start = windowStart;
      record.count = 1;
      return true;
    }

    record.count++;
    return record.count <= this.maxRequests;
  }

  // Compute window start aligned to windowMs boundary
  _computeWindowStart(timestamp) {
    return Math.floor(timestamp / this.windowMs) * this.windowMs;
  }
}

// 5 attempts per 15-minute window
const loginLimiter = new RateLimiter(15 * 60 * 1000, 5);

function hashPassword(password, salt) {
  return crypto.scryptSync(password, salt, 64).toString('hex');
}

function verifyPassword(password, salt, hash) {
  const computed = crypto.scryptSync(password, salt, 64);
  const expected = Buffer.from(hash, 'hex');
  if (computed.length !== expected.length) return false;
  return crypto.timingSafeEqual(computed, expected);
}

function createSession(userId, role) {
  const sessionId = crypto.randomBytes(32).toString('hex');
  const expires = Date.now() + 3600000;
  sessions.set(sessionId, { userId, role, expires });
  return sessionId;
}

function validateSession(sessionId) {
  if (!sessionId || typeof sessionId !== 'string') return null;
  const session = sessions.get(sessionId);
  if (!session) return null;
  if (Date.now() > session.expires) {
    sessions.delete(sessionId);
    return null;
  }
  return session;
}

function parseBody(req) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    let size = 0;
    req.on('data', chunk => {
      size += chunk.length;
      if (size > 4096) { reject(new Error('Body too large')); req.destroy(); return; }
      chunks.push(chunk);
    });
    req.on('end', () => {
      try { resolve(JSON.parse(Buffer.concat(chunks).toString())); }
      catch(e) { reject(e); }
    });
    req.on('error', reject);
  });
}

function getCookie(req, name) {
  const header = req.headers.cookie || '';
  const match = header.split(';').map(s => s.trim()).find(s => s.startsWith(name + '='));
  return match ? match.slice(name.length + 1) : null;
}

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, 'http://localhost');

  try {
    if (url.pathname === '/register' && req.method === 'POST') {
      const body = await parseBody(req);
      const { username, password } = body;

      if (!username || !password || typeof username !== 'string' || typeof password !== 'string') {
        res.writeHead(400, {'Content-Type':'application/json'});
        return res.end(JSON.stringify({error:'Invalid input'}));
      }
      if (username.length < 3 || username.length > 30 || !/^[a-zA-Z0-9_]+$/.test(username)) {
        res.writeHead(400, {'Content-Type':'application/json'});
        return res.end(JSON.stringify({error:'Invalid username'}));
      }
      if (password.length < 12) {
        res.writeHead(400, {'Content-Type':'application/json'});
        return res.end(JSON.stringify({error:'Password too short'}));
      }
      if (users.has(username)) {
        res.writeHead(409, {'Content-Type':'application/json'});
        return res.end(JSON.stringify({error:'User exists'}));
      }

      const salt = crypto.randomBytes(16).toString('hex');
      const hash = hashPassword(password, salt);
      users.set(username, { salt, hash, role: 'user' });

      res.writeHead(201, {'Content-Type':'application/json'});
      return res.end(JSON.stringify({success:true}));
    }

    if (url.pathname === '/login' && req.method === 'POST') {
      const body = await parseBody(req);
      const { username, password } = body;

      if (!username || !password || typeof username !== 'string' || typeof password !== 'string') {
        res.writeHead(400, {'Content-Type':'application/json'});
        return res.end(JSON.stringify({error:'Invalid input'}));
      }

      // Rate limiting by IP + username combination
      const clientIp = req.socket.remoteAddress || '127.0.0.1';
      const rateLimitKey = `${clientIp}:${username}`;

      if (!loginLimiter.isAllowed(rateLimitKey)) {
        res.writeHead(429, {'Content-Type':'application/json'});
        return res.end(JSON.stringify({error:'Too many attempts. Try again later.'}));
      }

      const user = users.get(username);
      if (!user) {
        // Dummy computation to prevent timing-based user enumeration
        crypto.scryptSync('dummy', 'dummysalt1234567', 64);
        res.writeHead(401, {'Content-Type':'application/json'});
        return res.end(JSON.stringify({error:'Invalid credentials'}));
      }

      if (!verifyPassword(password, user.salt, user.hash)) {
        res.writeHead(401, {'Content-Type':'application/json'});
        return res.end(JSON.stringify({error:'Invalid credentials'}));
      }

      const sessionId = createSession(username, user.role);
      res.writeHead(200, {
        'Content-Type':'application/json',
        'Set-Cookie': `sid=${sessionId}; HttpOnly; Secure; SameSite=Strict; Path=/`
      });
      return res.end(JSON.stringify({success:true, role: user.role}));
    }

    if (url.pathname === '/admin' && req.method === 'GET') {
      const sessionId = getCookie(req, 'sid');
      const session = validateSession(sessionId);
      if (!session || session.role !== 'admin') {
        res.writeHead(403, {'Content-Type':'application/json'});
        return res.end(JSON.stringify({error:'Forbidden'}));
      }
      res.writeHead(200, {'Content-Type':'application/json'});
      return res.end(JSON.stringify({message:'Welcome admin', users: Array.from(users.keys())}));
    }

    res.writeHead(404, {'Content-Type':'application/json'});
    res.end(JSON.stringify({error:'Not found'}));
  } catch(e) {
    res.writeHead(500, {'Content-Type':'application/json'});
    res.end(JSON.stringify({error:'Internal error'}));
  }
});

server.listen(3000);
